class TernaryQuantize(torch.autograd.Function):
    """Ternary quantization with per-channel scaling."""
    @staticmethod
    def forward(ctx, weight):
        # weight shape: [out_features, in_features]
        scale = weight.abs().mean(dim=1, keepdim=True).clamp(min=1e-12)
        w_norm = weight / scale
        w_clip = w_norm.clamp(-1, 1)
        w_round = w_clip.round()
        w_q = w_round * scale
        ctx.save_for_backward(scale, w_norm)
        return w_q, scale.squeeze(1)

    @staticmethod
    def backward(ctx, grad_w_q, grad_scale):
        scale, w_norm = ctx.saved_tensors
        mask = (w_norm.abs() <= 1).float()
        grad_weight = grad_w_q * mask / scale
        return grad_weight, None


def weight_quant(weight):
    """Ternary quantization using custom autograd Function."""
    return TernaryQuantize.apply(weight)


def activation_quant(x):
    """Absmax 8-bit activation quantization with STE."""
    Qb = 127
    scale = x.detach().abs().max().clamp(min=1e-12)
    x_normed = x / scale
    x_q = (x_normed * Qb).round().clamp(-Qb, Qb)
    x_q = (x_q - x_normed * Qb).detach() + x_normed * Qb
    return x_q, scale / Qb


class BitLinear(nn.Module):
    """BitNet b1.58 linear layer with ternary weights and per-channel scaling."""
    def __init__(self, in_features, out_features, bias=True):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.weight = nn.Parameter(torch.empty(out_features, in_features))
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_features))
        else:
            self.bias = None
        nn.init.normal_(self.weight, mean=0.0, std=0.02)

    def forward(self, x):
        w_q, w_scale = weight_quant(self.weight)
        x_q, x_scale = activation_quant(x)
        out = F.linear(x_q, w_q, None)
        out = out * (w_scale.view(1, -1) * x_scale)
        if self.bias is not None:
            out = out + self.bias
        return out
